{
  "gate_token": "y_vaSUNBRVA2AbfFs1EOEQ",
  "title": "The Mirror Road Home",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "A rescue begins at the edge of a broken city.",
      "visual_description": "On a cracked hilltop overlooking a ruined royal city at dusk, a mapmaker unrolls a charred map while a small metal fox sniffs the wind.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 2,
      "caption": "The lamp wakes with a warning.",
      "visual_description": "An oil lamp with a single glowing eye in its flame floats above the map, casting long shadows across torn royal banners stuck to a fence post.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "A reflection steps out of a puddle.",
      "visual_description": "From a rain puddle in the road, a figure in a clear diving helmet rises, coat shimmering with reflected city lights and falling embers.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "They approach the silent castle gates.",
      "visual_description": "Massive iron castle gates hang half-open under a smoke-orange sky; the clockwork fox creeps ahead while the mapmaker checks her brass compass.",
      "characters": ["mara_the_cartographer", "tin_fox", "glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "An official sleeps through the alarm bells.",
      "visual_description": "Just inside the gate, a plump official slumps against a pillar using a ledger book as a pillow, stamped papers fluttering on his sleeves as bells ring overhead.",
      "characters": ["sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "The lamp warns of a cursed tower.",
      "visual_description": "A leaning black tower wreathed in green mist looms above a courtyard; the oracle lamp's flame-eye narrows toward it as the mapmaker raises a hand to halt.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "Rumors of a great winged beast circle overhead.",
      "visual_description": "An enormous shadow with spread wings sweeps across torn banners and broken rooftops; the diver pulls the mapmaker into the shelter of a doorway.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 8,
      "caption": "The fox finds a hidden mirror passage.",
      "visual_description": "In a collapsed parlor, the clockwork fox paws at a tall cracked mirror that ripples like water, its blue glass eyes reflecting the glow.",
      "characters": ["tin_fox", "glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "The diver slips through the glass to scout.",
      "visual_description": "Half-submerged in the mirror's silver surface, the diver in the clear helmet waves back at the mapmaker, who sketches the room on a fresh map.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 10,
      "caption": "Armored patrols march past the broken fountain.",
      "visual_description": "From behind a toppled statue, the mapmaker and fox watch lines of empty animated armor clank past a dry fountain choked with old royal banners.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 11,
      "caption": "Frightened faces peer from shuttered windows.",
      "visual_description": "A narrow alley of tall houses, pale faces just visible behind cracked shutters; the oracle lamp dims its eye to a polite spark so it will not betray them.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 12,
      "caption": "A magic door demands a true name.",
      "visual_description": "A stone door carved with shifting runes blocks a stairwell; glowing letters drift in the air while the fox tilts its head and the diver presses a gloved palm to the stone.",
      "characters": ["glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 13,
      "caption": "The lamp whispers the answer.",
      "visual_description": "The oracle lamp tips toward the door, the flame-eye stretching into a word-shape; runes click open like turning gears as warm light spills onto the steps.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 14,
      "caption": "They find the lost one in a glass cell.",
      "visual_description": "In a vaulted chamber, a small figure curled inside a hanging glass sphere; the official is also there, snoring upright, ledger papers fused to a nearby pillar.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 15,
      "caption": "The diver swims up through the sphere to free them.",
      "visual_description": "The diver dives upward into the glass sphere as though it were a pond, coat rippling with reflected lanterns while the fox keeps watch by the doorway.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "Alarms wake even the sleepiest official.",
      "visual_description": "Red light floods the corridor; the official stumbles awake clutching his ledger pillow as the mapmaker drags him along by the sleeve, papers trailing.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 17,
      "caption": "They race for the long bridge out of the city.",
      "visual_description": "A narrow stone bridge stretches over a black river; the fox sprints ahead, the diver carries the rescued figure, and the mapmaker shoves the official forward under a sky full of sparks.",
      "characters": ["tin_fox", "glass_diver", "mara_the_cartographer", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "Safe on the far shore, the lamp blinks one last warning.",
      "visual_description": "On a misty riverbank beyond the ruined skyline, the group rests on mossy stones; the oracle lamp's eye glows softly while the fox winds its own key-tail.",
      "characters": ["oracle_lamp", "tin_fox", "mara_the_cartographer", "glass_diver", "sleeping_tax_collector"]
    }
  ]
}

